ALTER POLICY action_reminders_write ON public.cleaner_action_reminder_settings USING(tenant_id=public.current_tenant_id() AND (user_id=auth.uid() OR public.is_owner_or_manager())) WITH CHECK(tenant_id=public.current_tenant_id() AND (user_id=auth.uid() OR public.is_owner_or_manager()) AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=cleaner_action_reminder_settings.user_id AND p.tenant_id=cleaner_action_reminder_settings.tenant_id AND p.is_active));